// rr-watch-overwrites: every owner change made after the tool's decision, from the contact's owner history.
// The new owner is kept; this only records who changed it, when, and through what (Calendly, a user, a workflow).
// Rows are leads (cypress_rr_leads), from the list or booked through the booking link.
const encode = (obj) => Buffer.from(JSON.stringify(obj), 'utf8').toString('base64');

function findOverwrites(assignments, contacts) {
  const byId = new Map(contacts.map((c) => [String(c.id), c]));
  const rows = [];
  for (const a of assignments) {
    const c = byId.get(String(a.contact_id));
    const history = (c?.propertiesWithHistory?.hubspot_owner_id || [])
      .map((h) => ({ ...h, t: Date.parse(h.timestamp) }))
      .filter((h) => Number.isFinite(h.t) && h.t > Date.parse(a.created_at))
      .sort((x, y) => x.t - y.t);
    let prev = a.owner_id ? String(a.owner_id) : '';
    for (const h of history) {
      const value = h.value ? String(h.value) : '';
      if (value === prev) continue;
      rows.push({
        lead_id: a.id,
        contact_id: String(a.contact_id),
        from_owner_id: prev || null,
        to_owner_id: value || null,
        source_type: h.sourceType || '',
        source_id: h.sourceId || '',
        source_label: h.sourceLabel || '',
        changed_by_user_id: h.updatedByUserId ? String(h.updatedByUserId) : null,
        changed_at: new Date(h.t).toISOString(),
      });
      prev = value;
    }
  }
  return rows;
}

// The contact's name as HubSpot has it now, where it differs from the lead's (2026-10-30: a booking link visitor
// without a name gets one when they book, and the lead showed their email)
function findRenames(leads, contacts) {
  const byId = new Map(contacts.map((c) => [String(c.id), c]));
  const out = [];
  for (const l of leads) {
    const p = byId.get(String(l.contact_id))?.properties || {};
    const name = [p.firstname, p.lastname].filter(Boolean).join(' ').trim();
    if (name && name !== (l.contact_name || '')) out.push({ contact_id: String(l.contact_id), name });
  }
  return out;
}

const assignments = $('Recent leads').first().json.body.rows || [];
const contacts = $input.first().json.results || [];
const rows = findOverwrites(assignments, contacts);
const renames = findRenames(assignments, contacts);
return {
  "count": rows.length,
  "renamed": renames.length,
  "p": encode({ rows, renames }),
};

// rr-watch-overwrites, booked visits (2026-10-30, on request): a booking link visitor sent to the rotation (or a boosted
// rep) who books becomes a HubSpot contact owned by that rep (HubSpot meetings / Calendly set the owner). That counts as
// the rep's lead: the Save adds it to cypress_rr_leads (source 'booking'), and the cypress_rr_lead_counted trigger
// moves the rotation past them or uses one boosted lead, as for a list lead. One per email.
const encode = (obj) => Buffer.from(JSON.stringify(obj), 'utf8').toString('base64');
const SLACK_MS = 60 * 1000; // owner set up to a minute before the logged visit still counts (clock skew)

function findBooked(visits, contacts) {
  const byEmail = new Map();
  for (const c of contacts) {
    const p = c.properties || {};
    if (p.email) {
      byEmail.set(String(p.email).toLowerCase(), {
        id: String(c.id),
        name: [p.firstname, p.lastname].filter(Boolean).join(' '),
        owner: p.hubspot_owner_id ? String(p.hubspot_owner_id) : '',
        assigned: Date.parse(p.hubspot_owner_assigneddate || ''),
      });
    }
  }
  const out = new Map();
  for (const v of visits) {
    const c = byEmail.get(String(v.email).toLowerCase());
    if (!c || !c.owner || c.owner !== String(v.hs_owner_id)) continue;
    // the owner has to be set after the visit, so an owner the contact already had doesn't count
    if (!Number.isFinite(c.assigned) || c.assigned < Date.parse(v.created_at) - SLACK_MS) continue;
    // latest matching visit per email wins (visits come oldest first)
    out.set(v.email, {
      visit_id: v.id, email: v.email, contact_id: c.id, contact_name: c.name, previous_owner_id: v.previous_owner_id || null,
      owner_id: c.owner, rep_id: v.rep_id, rep_name: v.rep_name, boosted: v.route === 'boost', visited_at: v.created_at,
    });
  }
  return [...out.values()];
}

const visits = $('Recent visits').first().json.body.rows || [];
const contacts = $input.first().json.results || [];
const rows = findBooked(visits, contacts);
return {
  "count": rows.length,
  "p": encode({ rows }),
};
